package cn.haiduo.platform;
import com.fasterxml.jackson.databind.*;
import java.net.URI;
import java.util.*;
import java.math.BigDecimal;
import java.time.Instant;
public class ShopifyConnector implements PlatformConnector {
 private final URI endpoint;private final String token;private final ShopifyHttp http;private final ObjectMapper json=new ObjectMapper();
 private static final String FIELDS="id updatedAt cancelledAt displayFulfillmentStatus displayFinancialStatus currentSubtotalPriceSet { presentmentMoney { amount currencyCode } } lineItems(first:50) { nodes { quantity sku variant { id } } pageInfo { hasNextPage } }";
 public ShopifyConnector(URI endpoint,String token,ShopifyHttp http){this.endpoint=endpoint;this.token=token;this.http=http;}
 public static String validShop(String shop){if(shop==null||!shop.matches("[a-zA-Z0-9][a-zA-Z0-9-]{0,100}\\.myshopify\\.com"))throw new IllegalArgumentException("Invalid Shopify domain");return shop.toLowerCase(Locale.ROOT);}
 private JsonNode query(String query,Map<String,Object> vars)throws Exception{return http.post(endpoint,Map.of("Content-Type","application/json","X-Shopify-Access-Token",token),json.writeValueAsString(Map.of("query",query,"variables",vars))).path("data");}
 public List<Order> orders()throws Exception{long deadline=System.nanoTime()+java.time.Duration.ofMinutes(2).toNanos();var result=new ArrayList<Order>();String cursor="";Set<String> seen=new HashSet<>();for(int page=0;page<100;page++){if(System.nanoTime()>deadline)throw new IllegalStateException("Sync deadline exceeded");Map<String,Object> vars=new HashMap<>();vars.put("cursor",cursor.isEmpty()?null:cursor);var connection=query("query($cursor:String){orders(first:5,after:$cursor,sortKey:UPDATED_AT){nodes{"+FIELDS+"} pageInfo{hasNextPage endCursor}}}",vars).path("orders");if(!connection.path("nodes").isArray())throw new IllegalStateException("Missing orders response");for(var node:connection.path("nodes"))result.add(map(node));if(!connection.path("pageInfo").path("hasNextPage").asBoolean())return result;cursor=connection.path("pageInfo").path("endCursor").asText();if(cursor.isBlank()||!seen.add(cursor))throw new IllegalStateException("Invalid pagination cursor");}throw new IllegalStateException("Sync page limit exceeded");}
 public Optional<Order> order(String id)throws Exception{if(!id.matches("gid://shopify/Order/[0-9]+"))throw new IllegalArgumentException("Invalid order ID");var node=query("query($id:ID!){order(id:$id){"+FIELDS+"}}",Map.of("id",id)).path("order");return node.isMissingNode()||node.isNull()?Optional.empty():Optional.of(map(node));}
 public static Order map(JsonNode node){if(node.path("lineItems").path("pageInfo").path("hasNextPage").asBoolean())throw new IllegalStateException("Orders with more than 50 lines require bulk sync");var money=node.path("currentSubtotalPriceSet").path("presentmentMoney");String currency=money.path("currencyCode").asText(),status=node.path("displayFinancialStatus").asText();var items=new ArrayList<Item>();for(var line:node.path("lineItems").path("nodes")){int quantity=line.path("quantity").asInt();if(quantity<1||quantity>1000000)throw new IllegalArgumentException("Invalid platform quantity");items.add(new Item(line.path("variant").path("id").asText(),line.path("sku").asText(),quantity));}if(items.isEmpty()||!currency.matches("[A-Z]{3}"))throw new IllegalArgumentException("Invalid platform order");BigDecimal net=new BigDecimal(money.path("amount").asText());if(net.signum()<0||net.scale()>4||net.precision()>19)throw new IllegalArgumentException("Invalid platform amount");String refund=status.equals("REFUNDED")?"REFUNDED":status.equals("PARTIALLY_REFUNDED")?"PARTIAL":"NONE";String payment=Set.of("PAID","PARTIALLY_REFUNDED","REFUNDED").contains(status)?"PAID":status.equals("PENDING")?"PENDING":"UNKNOWN";return new Order(node.path("id").asText(),Instant.parse(node.path("updatedAt").asText()),currency,net,payment,refund,!node.path("cancelledAt").isNull()&&!node.path("cancelledAt").isMissingNode(),node.path("displayFulfillmentStatus").asText("UNKNOWN"),items);}
}
